CREATE TABLE public.civic_settings(id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), report_gain integer NOT NULL DEFAULT 2, consultation_gain integer NOT NULL DEFAULT 5, event_gain integer NOT NULL DEFAULT 8, association_gain integer NOT NULL DEFAULT 3, report_cooldown_minutes integer NOT NULL DEFAULT 60, reports_per_day integer NOT NULL DEFAULT 3, consultation_days integer NOT NULL DEFAULT 3, issue_stage_hours integer NOT NULL DEFAULT 24);
GRANT SELECT ON public.civic_settings TO authenticated; GRANT ALL ON public.civic_settings TO service_role; ALTER TABLE public.civic_settings ENABLE ROW LEVEL SECURITY; CREATE POLICY civic_settings_read ON public.civic_settings FOR SELECT TO authenticated USING(true);
CREATE TABLE public.institutions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), city_id text NOT NULL REFERENCES public.cities(id), institution_key text NOT NULL UNIQUE, name text NOT NULL, type text NOT NULL, description text NOT NULL, location_id uuid NOT NULL REFERENCES public.locations(id), role text NOT NULL, status text NOT NULL DEFAULT 'active', level text NOT NULL DEFAULT 'local', visibility text NOT NULL DEFAULT 'public', address text NOT NULL, opening_hours text NOT NULL, parent_id uuid REFERENCES public.institutions(id), responsible text NOT NULL DEFAULT 'Équipe municipale fictive', service_state text NOT NULL DEFAULT 'Ouvert');
GRANT SELECT ON public.institutions TO authenticated; GRANT ALL ON public.institutions TO service_role; ALTER TABLE public.institutions ENABLE ROW LEVEL SECURITY; CREATE POLICY public_institutions ON public.institutions FOR SELECT TO authenticated USING(status='active' AND visibility='public');
CREATE TABLE public.civic_stats(character_id uuid PRIMARY KEY REFERENCES public.characters(id) ON DELETE CASCADE, engagement integer NOT NULL DEFAULT 0 CHECK(engagement BETWEEN 0 AND 100));
GRANT SELECT ON public.civic_stats TO authenticated; GRANT ALL ON public.civic_stats TO service_role; ALTER TABLE public.civic_stats ENABLE ROW LEVEL SECURITY; CREATE POLICY own_civic_stats ON public.civic_stats FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid()));
CREATE TABLE public.civic_rewards(character_id uuid NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE, reward_key text NOT NULL, kind text NOT NULL, amount integer NOT NULL, occurred_at timestamptz NOT NULL DEFAULT public.game_now(), PRIMARY KEY(character_id,reward_key));
GRANT SELECT ON public.civic_rewards TO authenticated; GRANT ALL ON public.civic_rewards TO service_role; ALTER TABLE public.civic_rewards ENABLE ROW LEVEL SECURITY; CREATE POLICY own_civic_rewards ON public.civic_rewards FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid()));
CREATE TABLE public.public_issues(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), issue_key text UNIQUE, institution_id uuid NOT NULL REFERENCES public.institutions(id), city_id text NOT NULL REFERENCES public.cities(id), district_id text NOT NULL REFERENCES public.districts(id), location_id uuid NOT NULL REFERENCES public.locations(id), title text NOT NULL, description text NOT NULL, category text NOT NULL, severity integer NOT NULL DEFAULT 2 CHECK(severity BETWEEN 1 AND 5), status text NOT NULL DEFAULT 'reported' CHECK(status IN('reported','identified','studying','ongoing','resolved')), appeared_at timestamptz NOT NULL DEFAULT public.game_now(), stage_hours integer NOT NULL DEFAULT 24 CHECK(stage_hours>0), stage integer NOT NULL DEFAULT 0 CHECK(stage BETWEEN 0 AND 4));
GRANT SELECT ON public.public_issues TO authenticated; GRANT ALL ON public.public_issues TO service_role; ALTER TABLE public.public_issues ENABLE ROW LEVEL SECURITY; CREATE POLICY public_issues_read ON public.public_issues FOR SELECT TO authenticated USING(true);
CREATE UNIQUE INDEX one_open_issue_per_location_category ON public.public_issues(location_id,category) WHERE status<>'resolved';
CREATE TABLE public.issue_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), issue_id uuid NOT NULL REFERENCES public.public_issues(id) ON DELETE CASCADE, status text NOT NULL, description text NOT NULL, occurred_at timestamptz NOT NULL DEFAULT public.game_now(), UNIQUE(issue_id,status));
GRANT SELECT ON public.issue_history TO authenticated; GRANT ALL ON public.issue_history TO service_role; ALTER TABLE public.issue_history ENABLE ROW LEVEL SECURITY; CREATE POLICY public_issue_history ON public.issue_history FOR SELECT TO authenticated USING(true);
CREATE TABLE public.citizen_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), character_id uuid NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE, issue_id uuid NOT NULL REFERENCES public.public_issues(id), description text NOT NULL, created_at timestamptz NOT NULL DEFAULT public.game_now(), UNIQUE(character_id,issue_id));
GRANT SELECT ON public.citizen_reports TO authenticated; GRANT ALL ON public.citizen_reports TO service_role; ALTER TABLE public.citizen_reports ENABLE ROW LEVEL SECURITY; CREATE POLICY own_reports ON public.citizen_reports FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid()));
CREATE TABLE public.consultations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), consultation_key text UNIQUE, institution_id uuid NOT NULL REFERENCES public.institutions(id), city_id text NOT NULL REFERENCES public.cities(id), district_id text REFERENCES public.districts(id), location_id uuid NOT NULL REFERENCES public.locations(id), organization_id uuid REFERENCES public.organizations(id), issue_id uuid REFERENCES public.public_issues(id), title text NOT NULL, description text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN('open','closed')), closed_at timestamptz);
GRANT SELECT ON public.consultations TO authenticated; GRANT ALL ON public.consultations TO service_role; ALTER TABLE public.consultations ENABLE ROW LEVEL SECURITY; CREATE POLICY public_consultations ON public.consultations FOR SELECT TO authenticated USING(true);
CREATE TABLE public.consultation_options(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), consultation_id uuid NOT NULL REFERENCES public.consultations(id) ON DELETE CASCADE, label text NOT NULL, consequence text NOT NULL, sort_order integer NOT NULL DEFAULT 0, UNIQUE(consultation_id,sort_order));
GRANT SELECT ON public.consultation_options TO authenticated; GRANT ALL ON public.consultation_options TO service_role; ALTER TABLE public.consultation_options ENABLE ROW LEVEL SECURITY; CREATE POLICY public_consultation_options ON public.consultation_options FOR SELECT TO authenticated USING(true);
CREATE TABLE public.consultation_participations(character_id uuid NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE, consultation_id uuid NOT NULL REFERENCES public.consultations(id) ON DELETE CASCADE, option_id uuid NOT NULL REFERENCES public.consultation_options(id), participated_at timestamptz NOT NULL DEFAULT public.game_now(), PRIMARY KEY(character_id,consultation_id));
GRANT SELECT ON public.consultation_participations TO authenticated; GRANT ALL ON public.consultation_participations TO service_role; ALTER TABLE public.consultation_participations ENABLE ROW LEVEL SECURITY; CREATE POLICY own_consultation_choice ON public.consultation_participations FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid()));
CREATE TABLE public.public_decisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), decision_key text NOT NULL UNIQUE, institution_id uuid NOT NULL REFERENCES public.institutions(id), city_id text NOT NULL REFERENCES public.cities(id), district_id text REFERENCES public.districts(id), location_id uuid NOT NULL REFERENCES public.locations(id), issue_id uuid REFERENCES public.public_issues(id), consultation_id uuid UNIQUE REFERENCES public.consultations(id), title text NOT NULL, description text NOT NULL, category text NOT NULL DEFAULT 'Vie locale', decided_at timestamptz NOT NULL DEFAULT public.game_now(), status text NOT NULL DEFAULT 'applied' CHECK(status IN('planned','applied')), consequences jsonb NOT NULL DEFAULT '{}'::jsonb, applied_at timestamptz, news_id uuid REFERENCES public.news(id));
GRANT SELECT ON public.public_decisions TO authenticated; GRANT ALL ON public.public_decisions TO service_role; ALTER TABLE public.public_decisions ENABLE ROW LEVEL SECURITY; CREATE POLICY public_decisions_read ON public.public_decisions FOR SELECT TO authenticated USING(true);
ALTER TABLE public.organization_events ADD COLUMN institution_id uuid REFERENCES public.institutions(id), ADD COLUMN civic boolean NOT NULL DEFAULT false;
ALTER TABLE public.locations ADD COLUMN civic_state text NOT NULL DEFAULT 'normal', ADD COLUMN civic_project text;
ALTER TABLE public.activities ADD COLUMN civic_engagement_gain integer NOT NULL DEFAULT 0;
CREATE OR REPLACE FUNCTION public.award_civic(_cid uuid,_key text,_kind text,_amount integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.civic_rewards(character_id,reward_key,kind,amount) VALUES(_cid,_key,_kind,_amount) ON CONFLICT DO NOTHING; IF FOUND THEN INSERT INTO public.civic_stats(character_id,engagement) VALUES(_cid,LEAST(100,GREATEST(0,_amount))) ON CONFLICT(character_id) DO UPDATE SET engagement=LEAST(100,civic_stats.engagement+GREATEST(0,_amount)); END IF; END $$;
REVOKE ALL ON FUNCTION public.award_civic(uuid,text,text,integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.award_civic(uuid,text,text,integer) TO service_role;
CREATE OR REPLACE FUNCTION public.reward_civic_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE gain integer; citizen boolean; BEGIN IF TG_OP='INSERT' THEN SELECT e.civic OR o.kind='citizen' INTO citizen FROM public.organization_events e JOIN public.organizations o ON o.id=e.organization_id WHERE e.id=NEW.organization_event_id; IF citizen THEN SELECT CASE WHEN EXISTS(SELECT 1 FROM public.organization_events WHERE id=NEW.organization_event_id AND civic) THEN event_gain ELSE association_gain END INTO gain FROM public.civic_settings WHERE id=1; NEW.civic_engagement_gain:=COALESCE(gain,0); END IF; RETURN NEW; END IF; IF OLD.status='running' AND NEW.status='completed' AND NEW.end_time<=public.game_now() AND NEW.civic_engagement_gain>0 THEN PERFORM public.award_civic(NEW.character_id,'activity:'||NEW.id,'event',NEW.civic_engagement_gain); END IF; RETURN NEW; END $$;
CREATE TRIGGER civic_activity_snapshot BEFORE INSERT ON public.activities FOR EACH ROW EXECUTE FUNCTION public.reward_civic_activity();
CREATE TRIGGER civic_activity_reward AFTER UPDATE OF status ON public.activities FOR EACH ROW EXECUTE FUNCTION public.reward_civic_activity();
REVOKE ALL ON FUNCTION public.reward_civic_activity() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.civic_actor() RETURNS public.characters LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.characters; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Non connecté'; END IF; SELECT * INTO c FROM public.characters WHERE user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Personnage introuvable'; END IF; PERFORM public.settle_daily_life(c.id); INSERT INTO public.civic_stats(character_id) VALUES(c.id) ON CONFLICT DO NOTHING; RETURN c; END $$;
REVOKE ALL ON FUNCTION public.civic_actor() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.civic_actor() TO service_role;
CREATE OR REPLACE FUNCTION public.report_civic_issue(_category text,_location_id uuid,_description text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.characters; l public.locations; iid uuid; responsible uuid; cfg public.civic_settings; rid uuid; BEGIN c:=public.civic_actor(); SELECT * INTO cfg FROM public.civic_settings WHERE id=1; IF _category IS NULL OR _category NOT IN('Voirie','Propreté','Éclairage','Espaces verts','Transport','Logement étudiant','Sport','Culture') THEN RAISE EXCEPTION 'Catégorie inconnue'; END IF; _description:=btrim(COALESCE(_description,'')); IF length(_description)<20 OR length(_description)>500 THEN RAISE EXCEPTION 'Description : entre 20 et 500 caractères'; END IF; SELECT l2.* INTO l FROM public.locations l2 JOIN public.districts d ON d.id=l2.district_id WHERE l2.id=_location_id AND l2.city_id=c.city_id AND d.city_id=c.city_id AND d.available AND l2.accessible; IF NOT FOUND THEN RAISE EXCEPTION 'Choisissez un lieu accessible de votre ville'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('report:'||l.id||':'||_category,0)); IF EXISTS(SELECT 1 FROM public.citizen_reports WHERE character_id=c.id AND created_at>public.game_now()-cfg.report_cooldown_minutes*interval '1 minute') THEN RAISE EXCEPTION 'Attendez avant un nouveau signalement'; END IF; IF (SELECT count(*) FROM public.citizen_reports WHERE character_id=c.id AND (created_at AT TIME ZONE 'UTC')::date=(public.game_now() AT TIME ZONE 'UTC')::date)>=cfg.reports_per_day THEN RAISE EXCEPTION 'Limite quotidienne de signalements atteinte'; END IF; SELECT id INTO iid FROM public.public_issues WHERE location_id=l.id AND category=_category AND status<>'resolved' FOR UPDATE; IF iid IS NULL THEN SELECT id INTO responsible FROM public.institutions WHERE city_id=c.city_id AND type='Service municipal' AND institution_key=c.city_id||':service'; INSERT INTO public.public_issues(institution_id,city_id,district_id,location_id,title,description,category,stage_hours) VALUES(responsible,c.city_id,l.district_id,l.id,_category||' — '||l.name,'Un problème a été signalé par les habitants. Le service municipal examine la situation.',_category,cfg.issue_stage_hours) RETURNING id INTO iid; INSERT INTO public.issue_history(issue_id,status,description) VALUES(iid,'reported','Signalement reçu par le service municipal.'); END IF; INSERT INTO public.citizen_reports(character_id,issue_id,description) VALUES(c.id,iid,_description) RETURNING id INTO rid; PERFORM public.award_civic(c.id,'report:'||iid,'report',cfg.report_gain); INSERT INTO public.notifications(user_id,title,body,world_at) VALUES(c.user_id,'Signalement enregistré',_category||' — '||l.name,public.game_now()); RETURN rid; END $$;
REVOKE ALL ON FUNCTION public.report_civic_issue(text,uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.report_civic_issue(text,uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.participate_consultation(_consultation_id uuid,_option_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.characters; co public.consultations; gain integer; BEGIN c:=public.civic_actor(); SELECT * INTO co FROM public.consultations WHERE id=_consultation_id FOR UPDATE; IF NOT FOUND OR co.city_id<>c.city_id OR co.status<>'open' OR public.game_now()<co.starts_at OR public.game_now()>=co.ends_at THEN RAISE EXCEPTION 'Consultation fermée ou inaccessible'; END IF; IF NOT EXISTS(SELECT 1 FROM public.consultation_options WHERE id=_option_id AND consultation_id=co.id) THEN RAISE EXCEPTION 'Option inconnue'; END IF; IF EXISTS(SELECT 1 FROM public.consultation_participations WHERE character_id=c.id AND consultation_id=co.id) THEN RAISE EXCEPTION 'Vous avez déjà participé à cette consultation'; END IF; INSERT INTO public.consultation_participations(character_id,consultation_id,option_id) VALUES(c.id,co.id,_option_id); SELECT consultation_gain INTO gain FROM public.civic_settings WHERE id=1; PERFORM public.award_civic(c.id,'consultation:'||co.id,'consultation',gain); INSERT INTO public.notifications(user_id,title,body,world_at) VALUES(c.user_id,'Participation citoyenne enregistrée',co.title,public.game_now()); END $$;
REVOKE ALL ON FUNCTION public.participate_consultation(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.participate_consultation(uuid,uuid) TO authenticated;